function polygon(points,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fill();}
function background(t){const g=ctx.createLinearGradient(0,0,0,H*.68);g.addColorStop(0,'#426879');g.addColorStop(.52,'#b3b19c');g.addColorStop(1,'#e1ac79');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
const sunX=W*.77,sunY=H*.22,sunR=Math.min(W,H)*.09;const glow=ctx.createRadialGradient(sunX,sunY,0,sunX,sunY,sunR*2.7);glow.addColorStop(0,'rgba(255,230,164,.65)');glow.addColorStop(1,'rgba(255,220,160,0)');ctx.fillStyle=glow;ctx.fillRect(sunX-sunR*3,sunY-sunR*3,sunR*6,sunR*6);ctx.fillStyle='#ffdda0';ctx.beginPath();ctx.arc(sunX,sunY,sunR*.72,0,Math.PI*2);ctx.fill();
const horizon=H*.355;ctx.fillStyle='#687c6f';ctx.beginPath();ctx.moveTo(0,horizon+10);for(let x=0;x<=W+20;x+=20){const ridge=Math.sin(x*.009+1.1)*H*.045+Math.sin(x*.021)*H*.018;ctx.lineTo(x,horizon-ridge+20);}ctx.lineTo(W,horizon+60);ctx.lineTo(0,horizon+60);ctx.fill();ctx.fillStyle='#344d48';ctx.beginPath();ctx.moveTo(0,horizon+24);for(let x=0;x<=W+20;x+=18){ctx.lineTo(x,horizon+Math.sin(x*.014+2.3)*H*.038+Math.sin(x*.033)*H*.016+32);}ctx.lineTo(W,horizon+80);ctx.lineTo(0,horizon+80);ctx.fill();
ctx.fillStyle='#648449';ctx.fillRect(0,horizon+46,W,H-horizon);ctx.fillStyle='rgba(232,210,157,.28)';ctx.fillRect(0,horizon+52,W,5);}
function drawRoad(){const strips=[];for(let i=0;i<=MAX_VIEW;i++){const seg=segments[wrap(Math.floor(player)+i)],dist=i+1.05;strips.push({seg,dist,p:project(dist,seg.x,seg.height),id:wrap(Math.floor(player)+i)});}
for(let i=strips.length-1;i>0;i--){const a=strips[i],b=strips[i-1],p=a.p,q=b.p;if(p.y<H*.34||q.y>H*1.2)continue;const halfP=ROAD*.5*p.scale*H,halfQ=ROAD*.5*q.scale*H;const shoulderP=halfP*.13,shoulderQ=halfQ*.13;const leftP=p.x-halfP,rightP=p.x+halfP,leftQ=q.x-halfQ,rightQ=q.x+halfQ;const stripe=Math.floor(a.id/3)%2===0;
polygon([[0,p.y],[W,p.y],[W,q.y],[0,q.y]],stripe?'#698449':'#71894b');polygon([[leftP-shoulderP,p.y],[leftP,p.y],[leftQ,q.y],[leftQ-shoulderQ,q.y]],stripe?'#e4e0ce':'#d94c4d');polygon([[rightP,p.y],[rightP+shoulderP,p.y],[rightQ+shoulderQ,q.y],[rightQ,q.y]],stripe?'#e4e0ce':'#d94c4d');polygon([[leftP,p.y],[rightP,p.y],[rightQ,q.y],[leftQ,q.y]],stripe?'#4b4e4b':'#454846');
const edgeP=Math.max(1,halfP*.012),edgeQ=Math.max(1,halfQ*.012);polygon([[leftP+shoulderP*.35,p.y],[leftP+shoulderP*.35+edgeP,p.y],[leftQ+shoulderQ*.35+edgeQ,q.y],[leftQ+shoulderQ*.35,q.y]],'rgba(255,255,255,.82)');polygon([[rightP-shoulderP*.35-edgeP,p.y],[rightP-shoulderP*.35,p.y],[rightQ-shoulderQ*.35,q.y],[rightQ-shoulderQ*.35-edgeQ,q.y]],'rgba(255,255,255,.82)');
if(Math.floor(a.id/4)%2===0){const line=halfP*.014,line2=halfQ*.014;polygon([[p.x-line,p.y],[p.x+line,p.y],[q.x+line2,q.y],[q.x-line2,q.y]],'rgba(245,242,224,.78)');}
if(a.id%10===0&&p.y<H*.82&&p.y>H*.36){for(const side of [-1,1]){const xx=p.x+side*(halfP+shoulderP*1.6);const hh=Math.max(3,halfP*.14);ctx.fillStyle='#e7e5d8';ctx.fillRect(xx-1,p.y-hh,2,hh);ctx.fillStyle='#df4a4b';ctx.fillRect(xx-2,p.y-hh,4,Math.max(2,hh*.3));}}
}}
function drawCar(x,baseY,height,color,number,isPlayer=false){const w=height*(isPlayer?.98:1.04),top=baseY-height;ctx.save();ctx.translate(x,0);ctx.fillStyle='rgba(0,0,0,.36)';ctx.beginPath();ctx.ellipse(0,baseY-height*.02,w*.75,height*.11,0,0,Math.PI*2);ctx.fill();
const wheelW=w*.18,wheelH=height*.24;ctx.fillStyle='#101316';for(const side of [-1,1]){ctx.fillRect(side*w*.45-wheelW/2,baseY-height*.37,wheelW,wheelH);ctx.fillRect(side*w*.46-wheelW/2,top+height*.31,wheelW,wheelH*.8);}
ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(-w*.1,baseY-height*.08);ctx.lineTo(-w*.61,baseY-height*.2);ctx.lineTo(-w*.52,baseY-height*.32);ctx.lineTo(-w*.32,baseY-height*.37);ctx.lineTo(-w*.24,top+height*.58);ctx.lineTo(-w*.13,top+height*.31);ctx.lineTo(-w*.11,top+height*.12);ctx.lineTo(w*.11,top+height*.12);ctx.lineTo(w*.13,top+height*.31);ctx.lineTo(w*.24,top+height*.58);ctx.lineTo(w*.32,baseY-height*.37);ctx.lineTo(w*.52,baseY-height*.32);ctx.lineTo(w*.61,baseY-height*.2);ctx.lineTo(w*.1,baseY-height*.08);ctx.closePath();ctx.fill();
ctx.fillStyle=isPlayer?'#f7f5e8':'rgba(250,248,232,.88)';ctx.fillRect(-w*.68,baseY-height*.24,w*1.36,height*.055);ctx.fillRect(-w*.26,top+height*.27,w*.52,height*.07);ctx.fillRect(-w*.44,baseY-height*.12,w*.88,height*.055);
ctx.fillStyle='#17282c';ctx.beginPath();ctx.moveTo(-w*.17,top+height*.22);ctx.lineTo(w*.17,top+height*.22);ctx.lineTo(w*.28,top+height*.5);ctx.lineTo(-w*.28,top+height*.5);ctx.closePath();ctx.fill();ctx.fillStyle='#ffdc8c';ctx.fillRect(-w*.09,top+height*.29,w*.18,height*.06);ctx.fillStyle='#f8f2d4';ctx.font=`900 ${Math.max(7,height*.11)}px system-ui`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(String(number),0,baseY-height*.19);ctx.restore();}
function drawRivals(){const list=[];for(const r of racers){let gap=r.p-player;if(gap<-LENGTH/2)gap+=LENGTH;else if(gap>LENGTH/2)gap-=LENGTH;if(gap>.15&&gap<48){const world=centerAt(r.p)+r.lane*ROAD*.5;const pp=project(gap+.95,world,roadHeightAt(r.p));list.push({r,gap,pp});}}list.sort((a,b)=>b.gap-a.gap);for(const {r,gap,pp} of list){const h=H*.24*pp.scale;if(h<8)continue;drawCar(pp.x,pp.y,h,r.color,r.number);}}
function render(t){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);const jx=shake?(Math.random()-.5)*shake*5:0,jy=shake?(Math.random()-.5)*shake*3:0;ctx.save();ctx.translate(jx,jy);background(t);drawRoad();drawRivals();const playerY=H*.89;drawCar(W*.5+(steer*.09*W),playerY,H*.145,'#d7ff3f',1,true);ctx.restore();}
function frame(now){const dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);render(now);raf=requestAnimationFrame(frame);}raf=requestAnimationFrame(frame);
})();
</script>
</body>
</html>

